// Convierte el formulario (ya validado por la web) en un Lead de Zoho.
const item = $input.first().json;
const b = item.body ?? item;

// Zoho rechaza los textos de una línea de más de 255 caracteres.
const clip = (value, max = 250) => String(value ?? '').trim().slice(0, max);

const email = clip(b.email, 254).toLowerCase();
if (!email) throw new Error('El formulario llegó sin email');

const full = clip(b.name || b.first_name, 100);
const parts = full.split(/\s+/).filter(Boolean);
// Zoho exige apellido (Last_Name). Si solo hay un nombre, va ahí.
const last = parts.length > 1 ? parts[parts.length - 1] : parts[0] || 'Sin nombre';
const first = parts.length > 1 ? parts.slice(0, -1).join(' ') : '';

const answers = b.answers && typeof b.answers === 'object' ? b.answers : {};
// Respuestas propias de cada formulario, una por línea. Guarda el ÚLTIMO envío:
// el correo al equipo conserva el detalle de cada uno.
const description = Object.entries(answers)
  .map(([key, value]) => key + ': ' + (Array.isArray(value) ? value.join(', ') : value))
  .join('\n')
  .slice(0, 5000);

const record = {
  First_Name: first,
  Last_Name: last,
  Email: email,
  Mobile: clip(answers.mobile, 30),
  Description: description,
  // Campos personalizados del módulo Leads (ver LEEME.md).
  YB_Segment: clip(b.segment),
  YB_Event: clip(b.event),
  Landing_Page: clip(b.landing_page),
  Primary_Interest: clip(b.primary_interest),
  Secondary_Interests: clip((b.secondary_interests || []).join(', ')),
  UTM_Source: clip(b.utm_source),
  UTM_Medium: clip(b.utm_medium),
  UTM_Campaign: clip(b.utm_campaign),
  UTM_Content: clip(b.utm_content),
  Referral_Code: clip(b.referral_code),
  Consent_Status: clip(b.consent_status),
  Last_Submission_Id: clip(b.submission_id),
  Last_Submitted_At: clip(b.submitted_at),
};

// No enviar campos vacíos: así un segundo envío no borra datos anteriores.
for (const key of Object.keys(record)) {
  if (record[key] === '' || record[key] === undefined || record[key] === null) delete record[key];
}

return [{ json: { record, segment: clip(b.segment), lead: { ...b, email } } }];

// Zoho responde 200/202 aunque rechace el registro (por ejemplo un campo que no
// existe). Sin esta comprobación el flujo diría "guardado" sin haber guardado nada.
// Si falla, el flujo termina con error y la web le pide a la persona que reintente.
const response = $input.first().json;
const result = Array.isArray(response.data) ? response.data[0] : null;

if (!result || result.status !== 'success' || !result.details || !result.details.id) {
  const why = result ? [result.code, result.message].filter(Boolean).join(' · ') : 'respuesta vacía';
  throw new Error('Zoho no guardó el contacto: ' + why);
}

return [{ json: { id: result.details.id, action: result.action || '' } }];

// Decide qué correos salen y los arma. Se ejecuta DESPUÉS de responder a la web,
// así un fallo de correo nunca afecta a la persona que envió el formulario.
//
// Ajustes: se leen de las Variables de n8n (YB_SITE_URL y YB_LEADS_TEAM_EMAIL) o, si no
// existen, de los valores de abajo.
const cfg = (name, fallback) => {
  try {
    return $vars[name] || fallback;
  } catch (e) {
    return fallback;
  }
};
const SITE = String(cfg('YB_SITE_URL', 'https://project-yates-production.up.railway.app')).replace(/\/$/, '');
const TEAM = String(cfg('YB_LEADS_TEAM_EMAIL', '')).trim();

// Protección contra abuso. Cualquiera puede escribir en un formulario el email de
// OTRA persona, y entonces le llegaría un correo nuestro. Por eso:
//  - a una misma dirección se le envía como máximo un correo cada 24 horas
//  - hay un tope diario de correos, por debajo del límite de Gmail
// Estos contadores viven en los datos del flujo: solo funcionan con el flujo
// ACTIVO (no en las pruebas manuales del editor).
const ONE_PER_ADDRESS_HOURS = 24;
const VISITOR_EMAILS_PER_DAY = 200;
const TEAM_EMAILS_PER_DAY = 100;

const NAVY = '#031f3c';
const SAND = '#b8a27a';
const IVORY = '#f6f3ec';

const lead = $('Preparar contacto').first().json.lead || {};
const answers = lead.answers && typeof lead.answers === 'object' ? lead.answers : {};

// Todo lo que escribió la persona se escapa antes de ir dentro de un correo HTML.
const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const oneLine = (value) => String(value ?? '').replace(/[\r\n\u0000-\u001f]+/g, ' ').trim();

const first = esc(oneLine(lead.first_name || lead.name) || 'there');
const host = SITE.replace(/^https?:\/\//, '');

const p = (html) =>
  `<p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#1f2d3d">${html}</p>`;
const small = (html) =>
  `<p style="margin:0 0 16px 0;font-size:12px;line-height:1.6;color:#5b6772">${html}</p>`;
const list = (items) =>
  `<ul style="margin:0 0 16px 0;padding-left:20px;font-size:15px;line-height:1.7;color:#1f2d3d">${items
    .map((html) => `<li style="margin:0 0 6px 0">${html}</li>`)
    .join('')}</ul>`;
const link = (label, path) => `<a href="${SITE}${path}" style="color:${NAVY}">${esc(label)}</a>`;

const footer = small(
  `You are receiving this email because you sent a request at ${esc(host)}. We use your details to respond to it. ` +
    `<a href="${SITE}/privacy" style="color:#5b6772">Privacy Policy</a>. ` +
    `If you did not make this request, you can ignore this message.`,
);

const shell = (heading, inner) => `<!doctype html><html><body style="margin:0;padding:0;background:${IVORY}">
<table width="100%" cellpadding="0" cellspacing="0" style="background:${IVORY};padding:32px 0"><tr><td align="center">
<table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border:1px solid #e4dfd3">
<tr><td style="background:${NAVY};padding:28px 36px">
<p style="margin:0;font-family:Arial,sans-serif;font-size:11px;letter-spacing:4px;text-transform:uppercase;color:${SAND}">YB University</p>
<h1 style="margin:10px 0 0 0;font-family:Georgia,serif;font-weight:normal;font-size:26px;line-height:1.2;color:#ffffff">${esc(heading)}</h1>
</td></tr>
<tr><td style="padding:32px 36px 8px 36px;font-family:Arial,sans-serif">${inner}</td></tr>
<tr><td style="padding:0 36px 28px 36px;font-family:Arial,sans-serif"><div style="height:1px;background:#e4dfd3;margin-bottom:16px"></div>${footer}</td></tr>
<tr><td style="background:${SAND};height:4px;font-size:0;line-height:0">&nbsp;</td></tr>
</table></td></tr></table></body></html>`;

const explore = list([link('Read the questions people ask most', '/faq'), link('See what the YB Learn program covers', '/learn')]);

const INTEREST_LABELS = {
  discovery_days: 'YB Discovery Days',
  step_aboard: 'YB Step Aboard',
  creator_challenge: 'YB Campus Creator Challenge',
  business_challenge: 'YB Business Challenge',
};

// BORRADOR: textos pendientes de aprobación del cliente. No prometen empleo,
// ingresos, licencias, acceso a yates ni nada que el documento no confirme. Lo que
// reciba cada persona del Discovery Pass sigue sin definirse, por eso estos
// correos solo confirman la recepción y dicen que se enviarán los siguientes pasos.
const TEMPLATES = {
  discovery_pass_registration: () => ({
    subject: 'Your YB Discovery Pass request',
    heading: 'Welcome to YB University',
    body:
      p(`Hi ${first},`) +
      p('Thanks for requesting your YB Discovery Pass. We have your details and will be in touch with next steps.') +
      p('In the meantime:') +
      explore +
      p('You don&#39;t need to know anything about yachts. You just need to be curious.'),
  }),

  program_inquiry: () => ({
    subject: 'We received your inquiry about YB University',
    heading: 'Your next chapter',
    body:
      p(`Hi ${first},`) +
      p('Thank you for your interest in YB University. We have your details and a member of our team will follow up with next steps.') +
      p('You don&#39;t have to make a career decision today. If you would like to look around in the meantime:') +
      explore +
      p('You are not starting over. You are bringing everything you&#39;ve learned into something new.'),
  }),

  business_inquiry: () => ({
    subject: 'We received your inquiry about the business of yachting',
    heading: 'Learn the business',
    body:
      p(`Hi ${first},`) +
      p('Thank you for your interest in YB University. We have your details and a member of our team will follow up with next steps.') +
      p('In the meantime:') +
      explore +
      p('Before you build a business in an unfamiliar industry, learn how that industry works.'),
  }),

  creator_application: () => ({
    subject: 'Your YB Creators Collective application',
    heading: 'Application received',
    body:
      p(`Hi ${first},`) +
      p('Thank you for applying to the YB Creators Collective. We review every application and will contact you about next steps.') +
      small(
        'Applying does not guarantee selection. Participation, vessel access, project assignments and any compensation are defined separately, and creator work and usage rights require a separate agreement.',
      ),
  }),

  campus_crew_registration: () => {
    const picked = (Array.isArray(answers.interests) ? answers.interests : [])
      .map((id) => INTEREST_LABELS[id])
      .filter(Boolean);
    return {
      subject: 'Welcome to the YB Campus Crew',
      heading: 'You are on the list',
      body:
        p(`Hi ${first},`) +
        p('Thanks for registering with the YB Campus Crew. We will let you know about upcoming campus activities.') +
        (picked.length ? p('You told us you are interested in:') + list(picked.map(esc)) : '') +
        (answers.ambassador === true
          ? p('We also noted your interest in becoming a Campus Crew Ambassador.')
          : ''),
    };
  },
};

const EVENT_LABELS = {
  discovery_pass_registration: 'Discovery Pass registration',
  program_inquiry: 'Program inquiry',
  business_inquiry: 'Business inquiry',
  creator_application: 'Creator application',
  campus_crew_registration: 'Campus Crew registration',
};

// ----- contadores (datos del flujo) -----
const store = $getWorkflowStaticData('global');
const now = Date.now();
const today = new Date(now).toISOString().slice(0, 10);
if (!store.visitorSent) store.visitorSent = {};
if (!store.day || store.day.date !== today) store.day = { date: today, visitor: 0, team: 0 };
for (const address of Object.keys(store.visitorSent)) {
  if (now - store.visitorSent[address] > ONE_PER_ADDRESS_HOURS * 3600 * 1000) delete store.visitorSent[address];
}

const out = [];
let visitorNote = 'Correo a la persona: enviado.';
const template = TEMPLATES[lead.event];

if (!lead.email || !template) {
  visitorNote = 'Correo a la persona: no aplica para este tipo de formulario.';
} else if (store.visitorSent[lead.email]) {
  visitorNote = 'Correo a la persona: NO enviado, esta dirección ya recibió uno en las últimas 24 horas.';
} else if (store.day.visitor >= VISITOR_EMAILS_PER_DAY) {
  visitorNote = `Correo a la persona: NO enviado, se alcanzó el tope diario (${VISITOR_EMAILS_PER_DAY}).`;
} else {
  const t = template();
  store.visitorSent[lead.email] = now;
  store.day.visitor += 1;
  out.push({ json: { to: lead.email, subject: t.subject, html: shell(t.heading, t.body) } });
}

// ----- aviso al equipo -----
if (TEAM && store.day.team < TEAM_EMAILS_PER_DAY) {
  store.day.team += 1;
  const label = EVENT_LABELS[lead.event] || oneLine(lead.event) || 'Form';
  const rows = [
    ['Name', oneLine(lead.name || lead.first_name)],
    ['Email', lead.email],
    ['Type', label],
    ['Landing page', lead.landing_page],
    ['Segment', lead.segment],
    ['Primary interest', lead.primary_interest],
    ['Secondary interests', (lead.secondary_interests || []).join(', ')],
    ['Program updates consent', lead.consent_status],
    ['utm_source', lead.utm_source],
    ['utm_medium', lead.utm_medium],
    ['utm_campaign', lead.utm_campaign],
    ['utm_content', lead.utm_content],
    ['Referral code', lead.referral_code],
    ...Object.entries(answers).map(([key, value]) => [key, Array.isArray(value) ? value.join(', ') : String(value)]),
    ['Submission', `${oneLine(lead.submission_id)} · ${oneLine(lead.submitted_at)}`],
  ].filter(([, value]) => value !== undefined && value !== null && String(value).trim() !== '');

  const table = `<table width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 16px 0">${rows
    .map(
      ([key, value]) =>
        `<tr><td style="padding:8px 12px 8px 0;border-bottom:1px solid #efeadf;width:170px;vertical-align:top;font-size:11px;letter-spacing:1.2px;text-transform:uppercase;color:#8a7448">${esc(key)}</td>` +
        `<td style="padding:8px 0;border-bottom:1px solid #efeadf;vertical-align:top;font-size:14px;line-height:1.6;color:#1f2d3d;white-space:pre-line">${esc(value)}</td></tr>`,
    )
    .join('')}</table>`;

  const subjectName = oneLine(lead.name || lead.first_name || lead.email).slice(0, 80);
  out.push({
    json: {
      to: TEAM,
      subject: `[YB] ${label}: ${subjectName}`,
      html: shell(`New ${label.toLowerCase()}`, table + small(esc(visitorNote))),
    },
  });
}

return out;
